tasks.command:
python3 -c "import pathlib,re;
pat=re.compile(r'class\s+TaskPlanSlice|record\s+TaskPlanSlice|struct\s+TaskPlanSlice|AppliedAtUtc|AppliedAt|CompletedAt');
root=pathlib.Path('.');
res=[str(p) for p in root.rglob('*') if p.is_file() and p.suffix in {'.cs','.razor'} and pat.search(p.read_text(errors='ignore'))];
print('\n'.join(res))"
